SELECT MEASURE(`blocked_by_risk`) AS total_blocked_by_risk
FROM workspace.approval_copilot.funnel_metrics
WHERE country = 'CO' AND business_date BETWEEN DATE'2026-07-01' AND DATE'2026-07-31';

SELECT SUM(`first_attempt_approved`) AS first_attempt_approved, SUM(`payments_sent`) AS payments_sent, try_divide(SUM(`first_attempt_approved`),SUM(`payments_sent`)) AS first_attempt_approval_rate
FROM `workspace`.`approval_copilot`.`gold_approval_daily`
WHERE `country` = 'CO' AND `is_cross_border` = true AND `business_date` BETWEEN DATE'2026-06-01' AND DATE'2026-06-30' AND `first_attempt_approved` IS NOT NULL AND `payments_sent` IS NOT NULL;
